create or replace function public.calculate_age(p_date_of_birth date) returns smallint language sql stable as $$ select extract(year from age(current_date, p_date_of_birth))::smallint $$;
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path = public, extensions as $$ begin insert into public.profiles(id,email,display_name,gender,date_of_birth) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name','Member'),'prefer_not_to_say',current_date - interval '18 years'); insert into public.profile_preferences(profile_id) values(new.id); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
create or replace function public.get_profile_completion(p_profile_id uuid default auth.uid()) returns integer language sql stable security definer set search_path = public as $$ select least(100, ((case when display_name is not null then 15 else 0 end)+(case when bio is not null then 20 else 0 end)+(case when city_id is not null then 10 else 0 end)+(case when exists(select 1 from public.profile_photos x where x.profile_id=p.id and x.moderation_status='approved') then 20 else 0 end)+(case when exists(select 1 from public.education x where x.profile_id=p.id) then 10 else 0 end)+(case when exists(select 1 from public.occupations x where x.profile_id=p.id) then 10 else 0 end)+(case when exists(select 1 from public.family_information x where x.profile_id=p.id) then 15 else 0 end))::integer from public.profiles p where p.id=p_profile_id $$;
create or replace function public.enforce_rate_limit(p_action text, p_limit integer, p_window interval) returns void language plpgsql security definer set search_path = public as $$ declare n integer; begin if auth.uid() is null then raise exception 'authentication required'; end if; if p_limit < 1 then raise exception 'invalid rate limit'; end if; select count(*) into n from public.rate_limit_events where subject=auth.uid()::text and action=p_action and occurred_at > now()-p_window; if n >= p_limit then raise exception 'rate limit exceeded' using errcode='P0001'; end if; insert into public.rate_limit_events(subject,action) values(auth.uid()::text,p_action); end $$;
create or replace function public.send_interest(p_recipient uuid, p_message text default null) returns uuid language plpgsql security definer set search_path = public as $$ declare v_id uuid; begin perform public.enforce_rate_limit('send_interest',20,interval '1 hour'); if p_recipient=auth.uid() or exists(select 1 from public.blocked_users where (blocker_id=auth.uid() and blocked_id=p_recipient) or (blocker_id=p_recipient and blocked_id=auth.uid())) then raise exception 'cannot send interest'; end if; insert into public.interests(sender_id,recipient_id,message) values(auth.uid(),p_recipient,p_message) returning id into v_id; insert into public.notifications(profile_id,type,title,data) values(p_recipient,'interest','New interest',jsonb_build_object('interest_id',v_id)); return v_id; end $$;
create or replace function public.accept_interest(p_interest_id uuid) returns uuid language plpgsql security definer set search_path = public as $$ declare i public.interests; v_low uuid; v_high uuid; v_match uuid; begin select * into i from public.interests where id=p_interest_id and recipient_id=auth.uid() and status='pending' for update; if not found then raise exception 'interest not found'; end if; update public.interests set status='accepted',responded_at=now() where id=i.id; v_low:=least(i.sender_id,i.recipient_id); v_high:=greatest(i.sender_id,i.recipient_id); insert into public.matches(user_low_id,user_high_id) values(v_low,v_high) on conflict(user_low_id,user_high_id) do update set status='active',unmatched_at=null returning id into v_match; insert into public.conversations(match_id) values(v_match) on conflict(match_id) do nothing; insert into public.notifications(profile_id,type,title,data) values(i.sender_id,'match','Your interest was accepted',jsonb_build_object('match_id',v_match)); return v_match; end $$;
create or replace function public.reject_interest(p_interest_id uuid) returns void language plpgsql security definer set search_path = public as $$ begin update public.interests set status='rejected',responded_at=now() where id=p_interest_id and recipient_id=auth.uid() and status='pending'; if not found then raise exception 'interest not found'; end if; end $$;
create or replace function public.block_user(p_blocked uuid) returns void language plpgsql security definer set search_path = public as $$ begin if p_blocked=auth.uid() then raise exception 'cannot block self'; end if; insert into public.blocked_users(blocker_id,blocked_id) values(auth.uid(),p_blocked) on conflict do nothing; update public.matches set status='blocked',unmatched_at=now() where (user_low_id=least(auth.uid(),p_blocked) and user_high_id=greatest(auth.uid(),p_blocked)); end $$;
create or replace function public.report_user(p_reported uuid,p_reason text) returns uuid language plpgsql security definer set search_path = public as $$ declare v uuid; begin perform public.enforce_rate_limit('report_user',10,interval '1 day'); insert into public.reports(reporter_id,reported_id,reason) values(auth.uid(),p_reported,p_reason) returning id into v; return v; end $$;
create or replace function public.update_last_seen() returns void language sql security definer set search_path=public as $$ update public.profiles set last_seen_at=now() where id=auth.uid() $$;
create or replace function public.mark_notification_read(p_notification_id uuid) returns void language sql security definer set search_path=public as $$ update public.notifications set read_at=coalesce(read_at,now()) where id=p_notification_id and profile_id=auth.uid() $$;
create or replace function public.search_profiles(p_limit integer default 30, p_cursor timestamptz default null) returns setof public.profiles language sql stable security definer set search_path=public as $$ select p.* from public.profiles p where p.id<>auth.uid() and p.deleted_at is null and p.is_discoverable and p.visibility <> 'private' and (p_cursor is null or p.created_at < p_cursor) and not exists(select 1 from public.blocked_users b where (b.blocker_id=auth.uid() and b.blocked_id=p.id) or (b.blocker_id=p.id and b.blocked_id=auth.uid())) order by p.created_at desc limit least(greatest(p_limit,1),100) $$;
revoke all on function public.create_profile(), public.enforce_rate_limit(text,integer,interval) from public; grant execute on function public.get_profile_completion(uuid), public.send_interest(uuid,text), public.accept_interest(uuid), public.reject_interest(uuid), public.block_user(uuid), public.report_user(uuid,text), public.update_last_seen(), public.mark_notification_read(uuid), public.search_profiles(integer,timestamptz) to authenticated;
